-- Esquema inicial. Ejecutar SOLO una vez en un proyecto nuevo.
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade,display_name text not null default 'Vecino',bio text not null default '',created_at timestamptz not null default now(),constraint profile_name_length check(char_length(display_name) between 2 and 60));
create table public.posts (id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,content text not null,created_at timestamptz not null default now(),constraint post_length check(char_length(content) between 1 and 2000));
create table public.comments (id uuid primary key default gen_random_uuid(),post_id uuid not null references public.posts(id) on delete cascade,user_id uuid not null references public.profiles(id) on delete cascade,content text not null,created_at timestamptz not null default now(),constraint comment_length check(char_length(content) between 1 and 500));
create table public.likes (post_id uuid not null references public.posts(id) on delete cascade,user_id uuid not null references public.profiles(id) on delete cascade,created_at timestamptz not null default now(),primary key(post_id,user_id));
create table public.follows (follower_id uuid not null references public.profiles(id) on delete cascade,following_id uuid not null references public.profiles(id) on delete cascade,created_at timestamptz not null default now(),primary key(follower_id,following_id),constraint no_self_follow check(follower_id<>following_id));
create table public.businesses (id uuid primary key default gen_random_uuid(),owner_id uuid not null references public.profiles(id) on delete cascade,name text not null,category text not null,description text,contact_url text,is_published boolean not null default false,created_at timestamptz not null default now());
create table public.reports (id uuid primary key default gen_random_uuid(),reporter_id uuid not null references public.profiles(id) on delete cascade,post_id uuid not null references public.posts(id) on delete cascade,reason text not null,created_at timestamptz not null default now());
create index on public.posts(created_at desc);create index on public.comments(post_id,created_at);create index on public.likes(post_id);
create function public.new_profile() returns trigger language plpgsql security definer set search_path='' as $$ begin insert into public.profiles(id,display_name) values(new.id,coalesce(nullif(left(trim(new.raw_user_meta_data->>'display_name'),60),''),'Vecino'));return new;end;$$;
create trigger after_signup after insert on auth.users for each row execute function public.new_profile();
alter table public.profiles enable row level security;alter table public.posts enable row level security;alter table public.comments enable row level security;alter table public.likes enable row level security;alter table public.follows enable row level security;alter table public.businesses enable row level security;alter table public.reports enable row level security;
create policy profiles_read on public.profiles for select to anon,authenticated using(true);
create policy profiles_update on public.profiles for update to authenticated using((select auth.uid())=id) with check((select auth.uid())=id);
create policy posts_read on public.posts for select to anon,authenticated using(true);
create policy posts_insert on public.posts for insert to authenticated with check((select auth.uid())=user_id);
create policy posts_delete on public.posts for delete to authenticated using((select auth.uid())=user_id);
create policy comments_read on public.comments for select to anon,authenticated using(true);
create policy comments_insert on public.comments for insert to authenticated with check((select auth.uid())=user_id);
create policy comments_delete on public.comments for delete to authenticated using((select auth.uid())=user_id);
create policy likes_read on public.likes for select to anon,authenticated using(true);
create policy likes_insert on public.likes for insert to authenticated with check((select auth.uid())=user_id);
create policy likes_delete on public.likes for delete to authenticated using((select auth.uid())=user_id);
create policy follows_read on public.follows for select to anon,authenticated using(true);
create policy follows_insert on public.follows for insert to authenticated with check((select auth.uid())=follower_id);
create policy follows_delete on public.follows for delete to authenticated using((select auth.uid())=follower_id);
create policy businesses_read on public.businesses for select to anon,authenticated using(is_published=true or (select auth.uid())=owner_id);
create policy businesses_insert on public.businesses for insert to authenticated with check((select auth.uid())=owner_id and is_published=false);
create policy businesses_update on public.businesses for update to authenticated using((select auth.uid())=owner_id) with check((select auth.uid())=owner_id and is_published=false);
create policy reports_insert on public.reports for insert to authenticated with check((select auth.uid())=reporter_id and char_length(reason) between 5 and 500);
